import { LegendItem } from '../types/legend.js';

export const findIndexOfMinMaxString = (items: LegendItem[]) => {
  if (items.length === 0) {
    return { longest: -1, shortest: -1 };
  }

  return items.reduce(
    (acc, current, index) => ({
      longest:
        current.name.length > items[acc.longest].name.length
          ? index
          : acc.longest,
      shortest:
        current.name.length < items[acc.shortest].name.length
          ? index
          : acc.shortest,
    }),
    { longest: 0, shortest: 0 },
  );
};
